def transform(grid):
    # Identify the distinct 3x3 nonzero objects; output the one that is not
    # part of the repeated pair of color-pattern shapes.
    R=len(grid); C=len(grid[0])
    objs=[]; seen=set()
    for r in range(R):
        for c in range(C):
            if grid[r][c] and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<R and 0<=nx<C and grid[ny][nx] and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                minr=min(y for y,x in cells); maxr=max(y for y,x in cells)
                minc=min(x for y,x in cells); maxc=max(x for y,x in cells)
                objs.append([[grid[minr+i][minc+j] for j in range(maxc-minc+1)] for i in range(maxr-minr+1)])
    # Output object matching a pattern in two-colored example? Task asks select
    # the object whose color composition is unique among 4 objects.
    from collections import Counter
    signatures=[tuple(sorted(Counter(v for row in o for v in row).items())) for o in objs]
    for i,s in enumerate(signatures):
        if signatures.count(s)==1:
            return objs[i]
    return objs[0]
